installed_revman_footer:
{
    axis.footer <- rcmetar.revman.axis.footer.layout(bundle, 
        layout)
    if (nzchar(bundle$style_blocks$axis_label)) {
        graphics::text(axis.footer$axis.x, axis.footer$axis.label.y, 
            bundle$style_blocks$axis_label, cex = cex)
    }
    spacing <- graphics::strheight("M", cex = cex) * 2.2
    rcmetar.draw.forest.direction.blocks(bundle, axis.footer, 
        axis.footer$axis.label.y - spacing, cex)
    invisible(NULL)
}
